[
  {
    "front": "Kỳ thi OLP AI Vòng Loại 2025 sử dụng nền tảng lập trình nào?",
    "back": "Jupyter Notebook do Ban Tổ Chức cung cấp thông qua liên kết web, mỗi đội có tài khoản riêng"
  },
  {
    "front": "Ngôn ngữ lập trình và phiên bản được sử dụng trong OLP AI?",
    "back": "Python 3.10 với các thư viện phổ biến đã cài đặt sẵn ở phiên bản ổn định mới nhất"
  },
  {
    "front": "Thí sinh có được phép cài thêm thư viện trong kỳ thi OLP AI không?",
    "back": "Không. Thí sinh không được phép cài thêm thư viện mới hoặc tải mô hình từ Internet"
  },
  {
    "front": "Quy trình thi OLP AI được chia thành mấy giai đoạn?",
    "back": "2 giai đoạn: Giờ 0-5 làm bài với dữ liệu huấn luyện, Giờ 6 sử dụng tập private test"
  },
  {
    "front": "Tập dữ liệu private test trong OLP AI được mở khóa khi nào?",
    "back": "Chỉ được mở khóa trong giờ cuối của cuộc thi, cần mật khẩu do BTC cung cấp"
  },
  {
    "front": "File nộp bài OLP AI cần chứa những gì?",
    "back": "File zip chứa: 1 file đầu ra (.csv hoặc .pkl) và 1 file mã nguồn (.ipynb)"
  },
  {
    "front": "Các nhóm thư viện chính được cài sẵn trong môi trường thi OLP AI?",
    "back": "Học máy/NLP, Xử lý dữ liệu, Xử lý ảnh, Trực quan hóa, và Tiện ích"
  },
  {
    "front": "Yêu cầu về file .ipynb khi nộp bài OLP AI?",
    "back": "File kết quả phải được tạo từ việc chạy tuần tự file .ipynb từ trên xuống dưới"
  },
  {
    "front": "Mỗi tác vụ trong OLP AI đi kèm với những gì?",
    "back": "Tệp notebook mẫu có mô tả tác vụ và mã nguồn mô hình mẫu tham khảo"
  },
  {
    "front": "Các bộ dữ liệu nào được cung cấp trong OLP AI?",
    "back": "Tập huấn luyện (train), tập kiểm tra công khai (public test), và tập test riêng (private test)"
  }
]
